import{_ as a,o as t,c as n,a2 as s}from"./chunks/framework.CWgsre3x.js";const u=JSON.parse('{"title":"Design system, languages and SEO","description":"","frontmatter":{},"headers":[],"relativePath":"websites/design-and-localization.md","filePath":"websites/design-and-localization.md"}'),i={name:"websites/design-and-localization.md"};function o(l,e,r,d,c,p){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="design-system-languages-and-seo" tabindex="-1">Design system, languages and SEO <a class="header-anchor" href="#design-system-languages-and-seo" aria-label="Permalink to &quot;Design system, languages and SEO&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release — source-reviewed draft</p><p>TransferBook+ v0.7.9 source baseline. Availability depends on installed release, permissions and configuration. Live publication is not established by this guide.</p></div><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Manage a website&#39;s visual identity independently from page content. Use approved assets and an authorized draft.</p><h2 id="design-and-content" tabindex="-1">Design and content <a class="header-anchor" href="#design-and-content" aria-label="Permalink to &quot;Design and content&quot;">​</a></h2><ol><li>In Design, review palette, typography, spacing, corner radii and button treatment.</li><li>Select approved local imagery. Avoid arbitrary HTML, scripts or external asset URLs in packages.</li><li>Use the block inspector to edit plain-text localized content. The platform supports English, Greek, Italian, French, German and Spanish (<code>en</code>, <code>el</code>, <code>it</code>, <code>fr</code>, <code>de</code>, <code>es</code>).</li><li>In Page &amp; SEO, review localized page metadata. Confirm that it accurately describes the page without unsupported business claims.</li><li>Check contrast diagnostics and inspect text, links and buttons in each preview. Normal text should meet at least 4.5:1 contrast for WCAG AA unless an applicable exception applies.</li></ol><h2 id="expected-result" tabindex="-1">Expected result <a class="header-anchor" href="#expected-result" aria-label="Permalink to &quot;Expected result&quot;">​</a></h2><p>The design system can be swapped independently of the page tree and localized content. A metadata or contrast check does not guarantee search indexing or full accessibility compliance.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>If an asset or locale is rejected, use supported formats and approved registry items. See <a href="./portable-packages.html">portable packages</a>.</p><h2 id="language-coverage-in-v0-7-10" tabindex="-1">Language coverage in v0.7.10 <a class="header-anchor" href="#language-coverage-in-v0-7-10" aria-label="Permalink to &quot;Language coverage in v0.7.10&quot;">​</a></h2><p><strong>Status: source-reviewed staging release.</strong> The inspector&#39;s <strong>6 Lang</strong> coverage audit reports translated, missing and fallback fields by locale. Coverage is not a translation quality certificate.</p><ol><li>Inspect coverage for each of the six supported locales.</li><li>Select a locale and use the English reference hints to review its text. Where offered, fill missing values from English without replacing existing translations.</li><li>Translate any copied English text and review the wording manually. Check page metadata, section text, buttons, navigation and mobile drawer in the selected locale.</li><li>Save and export the reviewed draft. A missing translation or fallback must not be advertised as completed localization merely because a field displays text.</li></ol>',13)])])}const h=a(i,[["render",o]]);export{u as __pageData,h as default};
